	var contentID string
	if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
		return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
	}
	if contentID == "" {
		return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
	}

	var gf GraphFile
	// The embedded graph obeys exactly the same name-encoding rule as a
	// standalone graph file: a raw name literal with invalid UTF-8 bytes or an
	// unpaired surrogate escape would be silently rewritten to U+FFFD, and a
	// corrupted upstream could then resolve to a genuinely different dataset.
	// The check runs on the graph's raw bytes and rejects the whole snapshot
	// even when the declared content identifier happens to match the
	// rewritten graph's digest. The raw scan is the shared one in
	// name_encoding.go applied to the graph document scope.
	if err := checkGraphNameEncoding(raw.Graph); err != nil {
		return nil, err
	}
	if err := json.Unmarshal(raw.Graph, &gf); err != nil {
		return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
	}
	// The embedded graph obeys exactly the same structural rules as a
	// standalone graph file, so the two readers can never judge one graph
	// differently.
	adj, err := validateGraphStructureFromFile(gf.Datasets)
	if err != nil {
		return nil, err
	}

	canonical, err := canonicalGraph(adj)
	if err != nil {
		return nil, err
	}
	if want := computeContentID(canonical); contentID != want {
		return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
	}

	return &SnapshotFile{
		FormatVersion: version,
		ContentID:     contentID,
		Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
	}, nil
}

// checkDuplicateFields applies the shared repeated-known-field rule (see
// duplicate_fields.go) to a snapshot, supplying the snapshot's own field
// scope and locations: formatVersion, contentId, and graph at the top level,
// datasets inside graph, and name and upstreams inside each dataset record.
// The embedded graph is scanned by the same checkGraphObject a standalone
// graph file uses, so the two readers can never judge one graph differently.
func checkDuplicateFields(data []byte) error {
	return runFieldScan(data, func(dec *json.Decoder) error {
		return checkObjectFields(dec, "at the top level of the snapshot", []knownField{
			{name: "formatVersion"},
			{name: "contentId"},
			{name: "graph", nested: func(dec *json.Decoder) error {
				return checkGraphObject(dec, `in "graph"`)
			}},
		})
	})
}

// CompareSnapshots returns the fixed-direction diff from old to new. Both
// inputs are assumed to have passed ParseSnapshot; the report is fully
// deterministic and identical for semantically identical comparisons.
func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
	oldAdj := adjacencyFromValidFile(oldSnap.Graph)
	newAdj := adjacencyFromValidFile(newSnap.Graph)

	// Dataset-level changes follow the shared old -> new rule the batch report
	// uses (see diffDatasets), so comparing two snapshots classifies new,
	// removed, and directly changed datasets exactly the way previewing or
	// applying the batch that turns one version into the other does.
	newNodes, removedNodes, changedNodes := diffDatasets(oldAdj, newAdj)

	added, removed := diffRelations(oldAdj, newAdj)

// decoding exactly as written: a raw string literal carrying bytes that are
// not valid UTF-8, or a \u escape forming an unpaired surrogate, would be
// silently rewritten to U+FFFD by the decoder, and the corrupted name could
// then collide with a genuinely different dataset (a removals entry meant
// for no one could delete the dataset really named "�"). The whole plan is
// refused instead, naming the field and the zero-based record or array
// position, even when the corrupted name would only have matched a dataset
// that does not exist. A genuine "�", correctly paired surrogate escapes,
// and names that merely look like escapes (a backslash before an ordinary
// letter) stay legal; unknown fields and their nested strings are not
// checked. The raw scan is shared with the graph readers and lives in
// name_encoding.go; this file only supplies the plan document scope.
func UnmarshalPlan(data []byte) (Plan, error) {
	var p Plan
	if err := checkPlanDuplicateFields(data); err != nil {
		return p, err
	}
	if err := json.Unmarshal(data, &p); err != nil {
		return p, fmt.Errorf("invalid plan JSON: %w", err)
	}
	if err := checkPlanNameEncoding(data); err != nil {
		return Plan{}, err
	}
	return p, nil
}

// checkGraphFileDuplicateFields applies the shared repeated-known-field rule
// (see duplicate_fields.go) to a standalone graph file, supplying the graph
// file's own location: datasets may be declared only once in the top-level
// graph object, and name and upstreams only once in each dataset record. The
// scan is the same checkGraphObject ParseSnapshot runs on the embedded graph,
// so preview, apply, and snapshot can never disagree about a graph that
// repeats a known field.
func checkGraphFileDuplicateFields(data []byte) error {
	return runFieldScan(data, func(dec *json.Decoder) error {
		return checkGraphObject(dec, "at the top level of the graph")
	})
}

// checkPlanDuplicateFields applies the shared repeated-known-field rule (see
// duplicate_fields.go) to a plan, supplying the plan's own field scope and
// locations: changes or removals at the top level, and name or upstreams
// inside each change record. A change record carries the same fields as a
// dataset record, so both use the shared datasetRecordFields scope and a plan
// can never be judged differently from the other documents about what counts
// as a repeated field.
func checkPlanDuplicateFields(data []byte) error {
	return runFieldScan(data, func(dec *json.Decoder) error {
		return checkObjectFields(dec, "at the top level of the plan", []knownField{
			{name: "changes", nested: func(dec *json.Decoder) error {
				return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
					return checkObjectFields(dec, fmt.Sprintf("in the change record at index %d of \"changes\"", index), datasetRecordFields)
				})
			}},
			{name: "removals"},
		})
	})
}

